head.script:
/**
 * @component
 * @company
 * @developer jcpark
 * @variableClone true
 * @notSupportBrowser
 * @version
 * @htmlRender
 * @icon
 * @disableIcon
 * @width 26px
 * @height 29px
 * @description
 */

/**
 * @property
 * @name style
 * @category 01.Basic & ETC
 * @type string
 * @option 
 * @default 
 * @necessary N
 * @bindparent 
 * @description HTML의 style 속성과 동일한 기능을 제공
 */

/**
 * @property
 * @name class
 * @category 01.Basic & ETC
 * @type string
 * @option 
 * @default udc_help_tooltip
 * @necessary N
 * @bindparent 
 * @description HTML의 class 속성과 동일한 기능을 제공
 */

/**
 * @property
 * @name id
 * @category 01.Basic & ETC
 * @type string
 * @option 
 * @default 
 * @necessary N
 * @bindparent 
 * @description ID값
 */

/**
 * @property
 * @name tooltipTitle
 * @category 01.Basic & ETC
 * @type string
 * @option 
 * @default 도움말 제목
 * @necessary N
 * @bindparent 
 * @description tooltip의 title 속성 설정
 */

/**
 * @property
 * @name tooltipContent
 * @category 01.Basic & ETC
 * @type string
 * @option 
 * @default 도움말 내용입니다.
 * @necessary N
 * @bindparent 
 * @description tooltip의 content 속성 설정
 */

/**
 * @property
 * @name visibleCloseButton
 * @category 01.Basic & ETC
 * @type combobox
 * @option [true,false]
 * @default true
 * @necessary N
 * @bindparent 
 * @description 닫기 버튼 노출 설정
 */

/**
 * @property
 * @name tooltipContentUseHtml
 * @category 01.Basic & ETC
 * @type combobox
 * @option [true,false]
 * @default false
 * @necessary N
 * @bindparent 
 * @description tooltip의 content 내용에 HTML 사용 설정 여부
 */

/**
 * @property
 * @name position
 * @category 05.Design
 * @type combobox
 * @option [top,bottom]
 * @default top
 * @necessary N
 * @bindparent 
 * @description tooltip의 위치 설정[top(default), bottom]
 */ 

scwin.onpageload = function() {
    scwin.init();
};

/**
 * @method
 * @name init
 * @description init properties
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.init = function() {
    const bindData = $p.getOptions();

    scwin.setTooltipTitle(bindData.tooltipTitle);
    scwin.setTooltipContent(bindData.tooltipContent, bindData.tooltipContentUseHtml);
    scwin.setVisibleCloseButton(bindData.visibleCloseButton);
    scwin.setPosition(bindData.position);

    scwin.setSenseReader();
};

/**
 * @event
 * @name btnToolTip_onclick
 * @description Tooltip click 이벤트
 * @param {event} e 이벤트 객체 
 * @example 
 */
scwin.btnToolTip_onclick = function(e) {
    grpToolTip.toggleClass("on");

    scwin.setSenseReader();
};

/**
 * @event
 * @name btnClose_onclick
 * @description Tootip 닫기 버튼 click 이벤트
 * @param {event} e 이벤트 객체 
 * @example 
 */
scwin.btnClose_onclick = function(e) {
    grpToolTip.toggleClass("on");

    scwin.setSenseReader();
};

/**
 * @method
 * @name setSenseReader
 * @description init 웹접근성 관련 속성 초기화
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.setSenseReader = function() {
    const hasClass = (grpToolTip.hasClass("on")) ? true : false;

    const objBtnToolTip = document.querySelector("#" + btnToolTip.getID());
    const objGrpToolTip = document.querySelector("#" + grpToolTip.getID());
    const objBtnClose = document.querySelector("#" + btnClose.getID());
    // 테이블 th에 있는 툴팁 스타일 적용
    const closestParent = objBtnToolTip.closest('.w2tb_th');
    (!comUtil.gfnIsEmpty(closestParent)) && (closestParent.style.paddingRight = "3.0rem");

    objBtnToolTip.setAttribute("aria-expanded", hasClass); // 도움말 버튼 활성화
    objBtnToolTip.setAttribute("aria-pressed", hasClass); // 도움말 버튼 활성화

    objGrpToolTip.setAttribute("aria-hidden", !hasClass);

    objBtnClose.setAttribute("aria-expanded", hasClass); // 닫기 버튼 활성화
    objBtnClose.setAttribute("aria-pressed", hasClass); // 닫기 버튼 활성화

    // 툴팁 최상위그룹 class="w2wframe udc_help_tooltip" 에 클래스 추가해서 z-index 우선순위 적용
    if (objGrpToolTip.classList.contains("on")) {
        objGrpToolTip.parentElement.parentElement.classList.add("on");
    } else {
        objGrpToolTip.parentElement.parentElement.classList.remove("on");
    }

    // 툴팁 우측에 위치할 때(화면 영역 벗어 났을 시) 스타일 추가하여 화면 영역 내에 위치하도록 변경 이벤트
    const boundRight = objBtnToolTip.getBoundingClientRect().right + objGrpToolTip.offsetWidth;
    if (boundRight < (window.innerWidth || document.documentElement.clientWidth)) {
        objGrpToolTip.style.right = "";
        objGrpToolTip.classList.remove("right-side");
    } else {
        objGrpToolTip.style.right = "0px";
        objGrpToolTip.classList.add("right-side");
    }
};

/**
 * @method
 * @name getTooltipTitle
 * @description Tooltip Title 값을 리턴한다.
 * @param 
 * @returns {string} tooltipTitle Tooltip Title 값을 리턴한다 
 * @hidden N
 * @exception 
 * @example 
 */
scwin.getTooltipTitle = function() {
    return grpTooltipTitle.render.innerText;
};

/**
 * @method
 * @name setTooltipTitle
 * @description Tooltip Title 값을 설정한다.
 * @param {string} tooltipTitle Tooltip Title 값을 설정한다 
 * @returns 
 * @hidden N
 * @exception 
 * @example 
 */
scwin.setTooltipTitle = function(tooltipTitle) {
    grpTooltipTitle.render.innerText = tooltipTitle;
};

/**
 * @method
 * @name getTooltipContent
 * @description Tooltip Content 값을 리턴한다.
 * @param 
 * @returns {string} tooltipContent Tooltip Content 값을 리턴한다 
 * @hidden N
 * @exception 
 * @example 
 */
scwin.getTooltipContent = function() {
    return grpTooltipContent.render.innerText;
};

/**
 * @method
 * @name setTooltipContent
 * @description Tooltip Content 값을 설정한다.
 * @param {string} tooltipContent setting tooltipContent
 * @param {string} tooltipContentUseHtml html을 사용여부 
 * @returns 
 * @hidden N
 * @exception 
 * @example 
 */
scwin.setTooltipContent = function(tooltipContent,tooltipContentUseHtml) {
    if(tooltipContentUseHtml) {
        grpTooltipContent.render.innerHTML = tooltipContent;
    }else {
        grpTooltipContent.render.innerText = tooltipContent;
    }
};

/**
 * @method
 * @name setVisibleCloseButton
 * @description Tooltip 닫기 버튼 노출 여부를 설정한다.
 * @param {boolean} flag 	Tooltip 닫기 버튼 노출 여부를 설정한다.  
 * @returns 
 * @hidden N
 * @exception 
 * @example 
 */
scwin.setVisibleCloseButton = function(flag) {
    btnClose.visible(flag);
};

/**
 * @method
 * @name setTooltipWidth
 * @description Tooltip의 width값 설정한다.
 * @param {string} value Tooltip의 width값 설정 
 * @returns 
 * @hidden N
 * @exception 
 * @example 
 */ 
scwin.setTooltipWidth = function(value) {
    grpToolTip.setStyle("width", value);
};

/**
 * @method
 * @name setPosition
 * @description Tooltip의 위치를설정[top(default), bottom]한다.
 * @param {string} position tooltip의 위치 설정[top(default), bottom] 
 * @returns 
 * @hidden N
 * @exception 
 * @example 
 */ 
scwin.setPosition = function(position = "top") {
    if (position === "top") {
        grpToolTip.removeClass("tooltip-bottom");
    } else {
        grpToolTip.addClass("tooltip-bottom");
    }
}
